  // ---------- Лейблы под фото ----------
  // Реальные: «Ранний доступ», «Проверено в Росреестре» — флаги Циана;
  // «Хорошая цена» — считаем сами: цена ≤ 85% медианы среди квартир той же комнатности.
  // Сгенерированные (в выдаче Циана таких полей нет): «Можно с детьми», «Можно с животными»
  // и промо-лейбл — детерминированно от id, чтобы не менялись между перезагрузками.
  const GOOD_PRICE_RATIO = 0.85;
  const PROMO_TITLES = ["Вид на воду", "Панорамные окна", "Дизайнерский ремонт", "Терраса", "Камин", "Вид на парк"];

  function hashId(id, salt) {
    let h = 2166136261;
    for (const ch of id + salt) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
    return (h >>> 0) / 4294967296;
  }

  function roomsKey(raw) {
    return raw.flatType === "rooms" ? Math.min(raw.rooms, 4) : raw.flatType;
  }

  function medianPriceByRooms(rawOffers) {
    const groups = {};
    rawOffers.forEach((raw) => {
      const key = roomsKey(raw);
      if (!groups[key]) groups[key] = [];
      groups[key].push(raw.price);
    });
    const medians = {};
    Object.entries(groups).forEach(([key, prices]) => {
      prices.sort((x, y) => x - y);
      medians[key] = prices[Math.floor(prices.length / 2)];
    });
    return medians;
  }

  function buildLabels(raw, medians) {
    const labels = [];
    if (raw.isEarlyAccess) labels.push("Ранний доступ");
    if (raw.price <= medians[roomsKey(raw)] * GOOD_PRICE_RATIO) labels.push("Хорошая цена");
    const curated = CURATED[raw.id];
    if (curated ? curated.kidsAllowed : hashId(raw.id, "kids") < 0.35) labels.push("Можно с детьми");
    if (curated ? curated.petsAllowed : hashId(raw.id, "pets") < 0.25) labels.push("Можно с животными");
    if (raw.isRosreestrChecked) labels.push("Проверено в Росреестре");
    return labels;
  }

  function buildPromo(raw) {
    if (CURATED[raw.id]) return null;
    const r = hashId(raw.id, "promo");
    if (r >= 0.3) return null;
    if (raw.street === "Невский проспект") return "Вид на Невский проспект";
    return PROMO_TITLES[Math.floor((r / 0.3) * PROMO_TITLES.length)];
  }

  function buildListings(rawOffers) {
    const medians = medianPriceByRooms(rawOffers);
    const curatedFirst = [...rawOffers].sort((x, y) => (CURATED[x.id]?.order ?? Infinity) - (CURATED[y.id]?.order ?? Infinity));
    return curatedFirst.map((raw) => ({
      ...raw,
      photos: CURATED[raw.id]?.photos ?? [],
      hasLayout: CURATED[raw.id]?.hasLayout ?? false,
      address: [raw.street, raw.house].filter(Boolean).join(", "),
      promoLabel: buildPromo(raw),
      labels: buildLabels(raw, medians),
      // Поля, на которых пока держатся старые офисные фильтры (цена за м², класс) —
      // уберём, когда переделаем фильтры под квартиры
      pricePerSqmYear: Math.max(100, Math.round((raw.price * 12) / raw.area / 100) * 100),
      officeClass: null,
    }));
  }

  const LISTINGS = buildListings(RAW_OFFERS);

  window.App = window.App || {};
  Object.assign(window.App, { RAW_OFFERS, CURATED, buildListings, LISTINGS });
